"use strict";
(function(){
const originalLoad=window.loadConfig,originalSave=window.saveConfig;
window.loadConfig=function(){const config=originalLoad();config.rentals=(config.rentals||[]).filter(r=>r.id!=='uber');config.rentals.push({id:'uber',name:'Uber',type:'VAN',collection:'0001-01-01',return:'9999-12-31',system:true});return config;};
window.saveConfig=function(config){originalSave({...config,rentals:(config.rentals||[]).filter(r=>r.id!=='uber')});};
Editor.rentalEmoji=function(id){const i=(loadConfig().rentals||[]).filter(r=>r.id!=='uber').findIndex(r=>r.id===id);return i<0?'':String(i+1).split('').map(n=>n+'\uFE0F\u20E3').join('');};
Editor.vehicleIcon=id=>id==='truck'?'🚚':id==='van'?'🚐':id==='uber'?'🚕':Editor.rentalEmoji(id)||'🚗';
Editor.vehicleTargets=(day,current)=>[...new Set(Editor.ids(day))].filter(id=>id!==current).map(id=>({id,icon:Editor.vehicleIcon(id),name:Editor.name(id)}));
Editor.resetDay=function(day){const d=Editor.dateKey(day);if(!confirm('Reset this day to its default vehicle allocation and run order? Base jobs will return to unassigned and locked times will be unlocked.'))return;delete Editor.state().stops[d];delete Editor.state().orders[d];delete Editor.state().timeOverrides?.[d];delete Editor.state().stopPhases?.[d];Object.keys(Editor.state().assignments).forEach(k=>{if(Editor.state().jobDates[k]===d)delete Editor.state().assignments[k];});Editor.refresh();};
const apply=Editor.apply;Editor.apply=function(day){const result=apply(day);day.rentals=(day.rentals||[]).filter(r=>r.id!=='uber'||r.rows.some(row=>row.editorStop||row.editorJob));[day.truck,day.van,...day.rentals].filter(Boolean).forEach(run=>run.rows.forEach(row=>{if(row.editorJob)row.transfers=row.transfers.replace(' | Dump ',' | Onsite Time: ');}));return result;};
window.renderConfig();
setTimeout(function(){
 function button(text,label,fn){const b=Editor.button(text,fn);b.type='button';b.classList.add('icon-btn');b.title=label;b.setAttribute('aria-label',label);b.dataset.tooltip=label;return b;}
 function styleAll(){document.querySelectorAll('button').forEach(b=>{const label=b.title||b.getAttribute('aria-label')||b.textContent.trim()||'Button';if(!b.title)b.title=label;if(!b.getAttribute('aria-label'))b.setAttribute('aria-label',label);b.dataset.tooltip=label;b.style.setProperty('border','1px solid #77808a','important');b.style.setProperty('background','#fff','important');b.style.setProperty('color','#20303c','important');b.style.setProperty('border-radius','6px','important');b.style.setProperty('padding','5px 8px','important');b.style.setProperty('min-width','32px','important');b.style.setProperty('min-height','30px','important');});}
 function decorate(schedule){document.querySelectorAll('#scheduleOutput .day').forEach((article,index)=>{const day=schedule[index];if(!day)return;
 article.querySelectorAll('.warning.base .run-actions').forEach((actions,n)=>{const assigned=new Set([day.truck,day.van,...(day.rentals||[])].filter(Boolean).flatMap(r=>r.rows.filter(row=>row.editorJob).map(row=>row.editorJob)));const jobs=(day.editorJobs||[]).filter(j=>!assigned.has(j.key)),job=jobs[n];if(!job)return;actions.replaceChildren(...Editor.vehicleTargets(day,null).map(v=>button(v.icon,'Assign base job to '+v.name,()=>Editor.assign(day,job,v.id))));});
 const primary=[['truck',day.truck],['van',day.van]].filter(([,r])=>r),special=(day.rentals||[]).filter(r=>r.rows?.length).slice().sort((a,b)=>a.id==='uber'?-1:b.id==='uber'?1:0),runs=primary.concat(special.map(r=>[r.id,r])),tables=[...article.querySelectorAll('.vehicle-pair .schedule-table'),...article.querySelectorAll('.special-runs .schedule-table')];
 const vehicleGlyph=t=>t==='🚚'||t==='🚐'||t==='🚕'||t==='🚗'||/^[0-9\uFE0F\u20E3]+$/.test(t);
 runs.forEach(([id,run],i)=>{const table=tables[i];if(!table)return;const shown=id==='truck'||id==='van'?run.rows:run.rows.filter(row=>row.editorStop||row.editorJob);shown.forEach((row,n)=>{if(!row.editorStop&&!row.editorJob)return;const tr=table.tBodies[0]?.rows[n];if(!tr)return;const job=row.editorJob&&(day.editorJobs||[]).find(j=>j.key===row.editorJob);let actions=tr.querySelector('.run-actions');if(!actions){actions=document.createElement('div');actions.className='run-actions';tr.cells[id==='uber'?0:1].append(actions);}Array.from(actions.querySelectorAll('button')).filter(b=>b.dataset.vehicleTarget||vehicleGlyph(b.textContent.trim())).forEach(b=>b.remove());
 Editor.vehicleTargets(day,id).forEach(v=>{const b=button(v.icon,(job?'Move base job to ':'Move stop to ')+v.name,()=>job?Editor.assign(day,job,v.id):Editor.move(day,row,v.id));b.dataset.vehicleTarget=v.id;actions.append(b);});
 if(job){Array.from(actions.querySelectorAll('button')).filter(b=>b.textContent.trim()==='❌').forEach(b=>b.remove());const b=button('❌','Return base job to unassigned bucket',()=>Editor.unassign(job));b.dataset.returnBase='true';actions.append(b);}else if(id==='uber'&&row.editorStop){let b=Array.from(actions.querySelectorAll('button')).find(b=>b.textContent.trim()==='Remove from Uber'||b.textContent.trim()==='❌');if(!b){b=button('❌','Remove from Uber and restore original vehicle',()=>{const s=Editor.state(),d=Editor.dateKey(day);if(s.stops[d])delete s.stops[d][row.editorStop];if(s.orders[d])delete s.orders[d].uber;Editor.refresh();});actions.append(b);}b.textContent='❌';b.title='Remove from Uber and restore original vehicle';b.setAttribute('aria-label',b.title);}
 });});
 });styleAll();}
 const render=window.renderSchedule;window.renderSchedule=function(schedule){const result=render(schedule);decorate(schedule);return result;};
 const configRender=window.renderConfig;window.renderConfig=function(){const result=configRender();styleAll();return result;};
 const tip=document.createElement('div');tip.id='buttonTooltip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);let active=null;
 function hide(){tip.hidden=true;if(active){const ids=(active.getAttribute('aria-describedby')||'').split(' ').filter(id=>id&&id!==tip.id);if(ids.length)active.setAttribute('aria-describedby',ids.join(' '));else active.removeAttribute('aria-describedby');active=null;}}
 function show(event){const b=event.target.closest?.('button');if(!b)return;hide();active=b;tip.textContent=b.dataset.tooltip||b.title||b.getAttribute('aria-label')||b.textContent.trim();const ids=new Set((b.getAttribute('aria-describedby')||'').split(' ').filter(Boolean));ids.add(tip.id);b.setAttribute('aria-describedby',[...ids].join(' '));tip.hidden=false;const rect=b.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(rect.left,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.max(8,Math.min(rect.bottom+6,innerHeight-tip.offsetHeight-8))+'px';}
 document.addEventListener('pointerover',show);document.addEventListener('focusin',show);document.addEventListener('pointerout',event=>{if(active&&!active.contains(event.relatedTarget))hide();});document.addEventListener('focusout',hide);document.addEventListener('click',hide);document.addEventListener('keydown',event=>{if(event.key==='Escape')hide();});window.addEventListener('scroll',hide,true);
 let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;styleAll();});}).observe(document.body,{childList:true,subtree:true});
 const style=document.createElement('style');style.textContent='#buttonTooltip{position:fixed;z-index:2147483647;max-width:320px;background:#20303c;color:white;padding:6px 9px;border-radius:5px;font:13px/1.35 system-ui;pointer-events:none}#buttonTooltip[hidden]{display:none!important}button:focus-visible{outline:3px solid #146bb8!important;outline-offset:2px}button:disabled{opacity:.45;cursor:not-allowed}@media print{#buttonTooltip{display:none!important}}';document.head.append(style);
 decorate(window.currentSchedule||[]);
},0);
})();
